import React from "react";
import { createRoot } from "react-dom/client";

const root = createRoot(document.getElementById("d1"));

root.render(
  <nav className="w-full bg-blue-600 text-white p-4 shadow-md mb-6 flex justify-between items-center rounded-b-2xl">
<h2 className="text-2xl font-bold">My Gallery</h2>
<ul className="flex gap-6 text-lg">
<li className="hover:underline cursor-pointer">Home</li>
<li className="hover:underline cursor-pointer">Gallery</li>
<li className="hover:underline cursor-pointer">Contact</li>
</ul>
</nav>
)
